$where=[];$args=[];
foreach(['from'=>'l.created_at >= ?','to'=>'l.created_at < DATE_ADD(?, INTERVAL 1 DAY)','user_id'=>'l.user_id = ?','action'=>'l.action = ?','module'=>'l.module = ?'] as $key=>$clause){$v=$_GET[$key]??'';if(is_string($v) && $v!==''){$where[]=$clause;$args[]=$v;}}
$logs=rows('SELECT l.*,u.name FROM audit_logs l LEFT JOIN users u ON u.id=l.user_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY l.id DESC LIMIT 500',$args);
?>
<section class="panel"><h2>Filter Logs</h2><form method="get" class="filters"><input type="hidden" name="page" value="audit"><?php field('From','from',$_GET['from']??'','date',false);field('To','to',$_GET['to']??'','date',false);selectField('User','user_id',[''=>'All Users']+array_column(rows('SELECT id,name FROM users ORDER BY name'),'name','id'),$_GET['user_id']??'',false);$actions=array_column(rows('SELECT DISTINCT action FROM audit_logs ORDER BY action'),'action');selectField('Action','action',[''=>'All Actions']+array_combine($actions,$actions),$_GET['action']??'',false);$modules=array_column(rows('SELECT DISTINCT module FROM audit_logs ORDER BY module'),'module');selectField('Module','module',[''=>'All Modules']+array_combine($modules,$modules),$_GET['module']??'',false); ?><a class="button secondary" href="<?= e(url('audit')) ?>">Reset</a><button>Apply</button></form></section>
<section class="panel"><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Date &amp; Time</th><th>User</th><th>Action</th><th>Module</th><th>Details</th></tr></thead><tbody><?php foreach($logs as $l): ?><tr><td><?= e($l['created_at']) ?></td><td><?= e($l['name']??'System') ?></td><td><?= badge($l['action']) ?></td><td><?= e($l['module']) ?></td><td><?= e($l['details']) ?></td></tr><?php endforeach;if(!$logs)emptyRow(5); ?></tbody></table></div><p class="muted">Showing up to 500 latest matching events. Narrow the date range to inspect older records.</p></section>
